SELECT * FROM resource_service_expertise
WHERE resource_id = #{resourceId}
ORDER BY skill_level DESC, service_id

SELECT * FROM resource_service_expertise
WHERE service_id = #{serviceId}
ORDER BY skill_level DESC, is_preferred DESC

SELECT * FROM resource_service_expertise
WHERE service_id = #{serviceId} AND skill_level = #{skillLevel}
ORDER BY is_preferred DESC, resource_id

mapper.update:
UPDATE resource_service_expertise SET
    skill_level = #{skillLevel},
    years_experience = #{yearsExperience},
    certification = #{certification},
    is_preferred = #{isPreferred}
WHERE resource_id = #{resourceId} AND service_id = #{serviceId}
